import{_ as t,o as s,c as e,a3 as n}from"./chunks/framework.BLaSdaBb.js";const k=JSON.parse('{"title":"多租户","description":"","frontmatter":{},"headers":[],"relativePath":"guide/multi-tenancy.md","filePath":"guide/multi-tenancy.md","lastUpdated":1786258560000}'),i={name:"guide/multi-tenancy.md"};function d(l,a,r,o,h,p){return s(),e("div",null,[...a[0]||(a[0]=[n(`<h1 id="多租户" tabindex="-1">多租户 <a class="header-anchor" href="#多租户" aria-label="Permalink to &quot;多租户&quot;">​</a></h1><p>框架提供租户上下文、租户解析中间件与数据隔离基础设施。本章讲隔离策略怎么选、上下文怎么切、写路径为什么和读路径不一样。</p><p>完整 API 见 <a href="./../packages/multitenancy">MultiTenancy</a> 与 <a href="./../packages/multitenancy-abstractions">MultiTenancy.Abstractions</a>。</p><h2 id="两种隔离策略" tabindex="-1">两种隔离策略 <a class="header-anchor" href="#两种隔离策略" aria-label="Permalink to &quot;两种隔离策略&quot;">​</a></h2><table tabindex="0"><thead><tr><th>策略</th><th>做法</th><th>适用</th></tr></thead><tbody><tr><td><strong>字段级隔离</strong></td><td>所有租户共库共表，靠 <code>Tenant_Id</code> 列 + 全局查询过滤器区分</td><td><strong>默认</strong>。租户多、单租户数据量不大</td></tr><tr><td>库级隔离</td><td>每个租户独立连接串</td><td>单租户数据量大、合规要求物理隔离</td></tr></tbody></table><p>两种可以混用——同一套代码里，一部分租户走共享库、一部分走独立库，由租户的连接配置决定。</p><h2 id="租户上下文" tabindex="-1">租户上下文 <a class="header-anchor" href="#租户上下文" aria-label="Permalink to &quot;租户上下文&quot;">​</a></h2><p><code>ICurrentTenant</code> 是运行期的租户身份：</p><div class="language-csharp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">csharp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">public</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> class</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> OrderService</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ICurrentTenant</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> currentTenant</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) : </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ITransientDependency</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    public</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> long</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">? </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">TenantId</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> currentTenant.Id;   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// null = 平台态（无租户上下文）</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h3 id="谁来设置它" tabindex="-1">谁来设置它 <a class="header-anchor" href="#谁来设置它" aria-label="Permalink to &quot;谁来设置它&quot;">​</a></h3><p>请求链路里由 <strong><code>XiHanTenantResolveMiddleware</code></strong> 设置，位置在<strong>认证之后</strong>（要读令牌里的租户 claim）、<strong>授权之前</strong>（授权判定要在租户上下文里进行）。</p><p>非请求场景（定时任务、后台作业、控制台）<strong>没有中间件</strong>，要自己切：</p><div class="language-csharp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">csharp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (currentTenant.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Change</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(tenantId))</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    // 这个块里所有仓储查询都带上该租户的过滤</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>框架的任务调度与后台作业已经内建了这一步——执行时按「参数 tenantId → 任务归属租户 → 当前异步上下文」的优先级解析并切换。</p><h3 id="平台态" tabindex="-1">平台态 <a class="header-anchor" href="#平台态" aria-label="Permalink to &quot;平台态&quot;">​</a></h3><p><code>Change(null)</code> 进入<strong>平台态</strong>：没有租户上下文。这是<strong>维护全局 / 跨租户数据的唯一合法入口</strong>。</p><h2 id="全局记录约定" tabindex="-1">全局记录约定 <a class="header-anchor" href="#全局记录约定" aria-label="Permalink to &quot;全局记录约定&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title"><code>TenantId = 0</code> 而不是 NULL</p><p>框架与 BasicApp 的约定是用 <strong><code>TenantId = 0</code></strong> 表示平台级/全局记录，<strong>不用 NULL</strong>。业务租户 Id 从 1 开始。</p><p>好处：列非空、索引干净、<code>WHERE TenantId IN (0, @current)</code> 这类合并查询写起来自然。</p><p>需要 <code>IsGlobal</code> 语义时用<strong>派生只读属性</strong> <code>IsGlobal =&gt; TenantId == 0</code>，<strong>不落库</strong>——避免两个字段漂移。</p></div><h2 id="读写口径不对称" tabindex="-1">读写口径不对称 <a class="header-anchor" href="#读写口径不对称" aria-label="Permalink to &quot;读写口径不对称&quot;">​</a></h2><p>这是多租户里最容易出事的一点：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>读：全局过滤器放行 TenantId IN (0, 当前租户)    ← 租户能读到平台全局数据</span></span>
<span class="line"><span>写：禁止改写 / 删除非本租户行（含 TenantId=0 的全局行）</span></span></code></pre></div><div class="danger custom-block"><p class="custom-block-title">「读共享」不等于「写共享」</p><p>如果写路径复用读的口径，租户就能改掉平台的全局数据——这是越权。</p><p>框架的做法：预读守卫校验取回行的 <code>TenantId</code>，条件写自动追加当前租户 <code>Where</code>。要维护全局数据，必须显式进平台态。</p></div><h2 id="实体怎么支持多租户" tabindex="-1">实体怎么支持多租户 <a class="header-anchor" href="#实体怎么支持多租户" aria-label="Permalink to &quot;实体怎么支持多租户&quot;">​</a></h2><p>继承 <code>SugarMultiTenant*</code> 系列基类即可——它们带 <code>Tenant_Id</code> 列并实现 <code>IMultiTenantEntity</code>。</p><div class="danger custom-block"><p class="custom-block-title">只加列不实现接口 = 隔离完全失效</p><p>全局过滤器是按 <code>AddTableFilter&lt;IMultiTenantEntity&gt;</code> 挂的。实体只加了 <code>TenantId</code> 列却没实现 <code>IMultiTenantEntity</code>，过滤器对它<strong>全程 no-op</strong>——所有租户都能看到所有数据，且没有任何报错。</p><p>用框架提供的 <code>SugarMultiTenant*</code> 基类就不会踩到；手写实体时务必确认接口实现上了。</p></div><h2 id="切换租户" tabindex="-1">切换租户 <a class="header-anchor" href="#切换租户" aria-label="Permalink to &quot;切换租户&quot;">​</a></h2><p>用户从一个租户切到另一个时，正确做法是<strong>复用会话、轮换令牌</strong>：</p><ul><li>不发登录事件、不新增设备记录；</li><li>在目标租户上下文里重建授权快照（不同租户可用功能不同）。</li></ul><p>如果实现成「登出再登录」，用户会收到两条登录通知、设备列表里多出一台设备。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>原因</th></tr></thead><tbody><tr><td>查到了别的租户数据</td><td>实体没实现 <code>IMultiTenantEntity</code>（只加了列）</td></tr><tr><td>后台任务里查不到数据</td><td>没有租户上下文，要 <code>Change(tenantId)</code></td></tr><tr><td>改不了全局数据</td><td>这是<strong>有意的</strong>——去平台态改</td></tr><tr><td>切租户后权限没变</td><td>授权快照没在目标上下文重建</td></tr><tr><td>平台态下反而查不到租户数据</td><td>平台态没有租户过滤，但业务查询可能自己带了条件</td></tr></tbody></table><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="./data">数据访问</a>：全局查询过滤器</li><li><a href="./authentication">认证与授权</a>：租户解析在管道里的位置</li><li><a href="./../packages/multitenancy">MultiTenancy 包</a>：完整 API</li></ul>`,33)])])}const g=t(i,[["render",d]]);export{k as __pageData,g as default};
